package utils_test

import (
	"encoding/hex"
	"cat240/global"
	"cat240/utils"
	"testing"
	"time"

	"go.uber.org/zap"
)

func TestParseData(t *testing.T) {
	logger, _ := zap.NewDevelopment()
    global.Logger = logger
    global.FilteredData = make(chan []byte, 100)
    global.ParsedData = make(chan []byte, 100)
	tests := []struct {
		name string
		data string
	}{
		{
			name: "test valid data cat240",
			data: "",
		},
		{
			name: "test valid data cat240",
			data: "",
		},
	}

	for test := range tests {
		t.Run(tests[test].name, func(t *testing.T) {
			data, err := hex.DecodeString(tests[test].data)
			if err != nil {
				t.Fatalf("Failed to decode hex string")
			}
			go utils.ParseData()
			global.FilteredData <- data
			select {
				case parsedData := <-global.ParsedData:
					t.Logf("Parsed data : %s", string(parsedData))
				case <-time.After( 5 * time.Second):
					t.Fatalf("Failed to parse data")
			}
		})
	}
	t.Run("test invalid data cat240", func(t *testing.T) {
		cat240Message := ""
		data, err := hex.DecodeString(cat240Message)
		if err != nil {
			t.Fatalf("Failed to decode hex string")
		}
		go utils.ParseData()
		global.FilteredData <- data
		select {
			case  <-global.ParsedData:
				t.Fatalf("Test is invalid")
			case <-time.After( 5 * time.Second):
				t.Logf("test is valid ")
		}
	})
}